package dock

// In-memory registry of live polar-agent WebSocket connections.
// Maps bot_user_id → live agentConn. One bot may have at most one
// agent attached at a time; new connect kicks the old one off.
//
// This is the transport layer; the chat / ai_agent integration
// (where tool_call messages get generated by an LLM and routed
// here) lands in the next phase. For now there's a debug endpoint
// the user can hit to manually fire a tool_call and verify the
// round-trip.

import (
	"encoding/json"
	"errors"
	"sync"
	"time"
)

const (
	agentToolCallTimeout = 60 * time.Second
)

// agentToolCall is what the platform sends to a connected agent.
// id is a server-generated correlation token; the agent echoes it
// back in its agentToolResult so we can match the response.
type agentToolCall struct {
	Kind string         `json:"kind"` // always "tool_call"
	ID   string         `json:"id"`
	Tool string         `json:"tool"`
	Args map[string]any `json:"args"`
}

// agentToolResult is the agent's response. Echoes the call id.
type agentToolResult struct {
	Kind   string `json:"kind"` // "tool_result"
	ID     string `json:"id"`
	OK     bool   `json:"ok"`
	Stdout string `json:"stdout,omitempty"`
	Stderr string `json:"stderr,omitempty"`
	// Output is the shape-specific return (file content for read_file,
	// dir entries for list_dir, exit code for run_cmd). Tool-specific.
	Output map[string]any `json:"output,omitempty"`
	Error  string         `json:"error,omitempty"`
}

// agentConn is one live polar-agent. The receive loop dispatches
// incoming messages by Kind; pending tool calls + chat replies are
// each tracked separately so the platform can match responses to
// requests.
type agentConn struct {
	tokenID    string
	userID     string
	botUserID  string
	workspaceID string
	workdir    string
	// Capabilities the agent declared in its hello frame. Today
	// the only meaningful one is "kimi" which means the agent has
	// kimi-cli installed and is willing to pipe chat content
	// through it (passthrough mode). Bots without this capability
	// stay on the platform-driven tool_call loop.
	capabilities []string
	send       chan []byte
	close      chan struct{}

	pendingMu sync.Mutex
	pending   map[string]chan agentToolResult

	chatPendingMu sync.Mutex
	chatPending   map[string]chan agentChatReply
}

func (c *agentConn) hasCapability(name string) bool {
	for _, cap := range c.capabilities {
		if cap == name {
			return true
		}
	}
	return false
}

func (c *agentConn) trackPending(id string) chan agentToolResult {
	ch := make(chan agentToolResult, 1)
	c.pendingMu.Lock()
	c.pending[id] = ch
	c.pendingMu.Unlock()
	return ch
}

func (c *agentConn) deliverResult(r agentToolResult) {
	c.pendingMu.Lock()
	ch, ok := c.pending[r.ID]
	if ok {
		delete(c.pending, r.ID)
	}
	c.pendingMu.Unlock()
	if ok {
		ch <- r
	}
}

// agentChatMessage is the platform → agent envelope when routing a
// user-typed chat message into a kimi-cli passthrough agent. The
// agent spawns its local kimi-cli with this Content as input
// (resuming the per-thread session) and pipes stdout back as
// agentChatReply.
type agentChatMessage struct {
	Kind     string `json:"kind"` // "chat_message"
	ID       string `json:"id"`
	ThreadID int64  `json:"thread_id"`
	Content  string `json:"content"`
}

type agentChatReply struct {
	Kind    string `json:"kind"` // "chat_reply"
	ID      string `json:"id"`
	OK      bool   `json:"ok"`
	Content string `json:"content,omitempty"`
	Stderr  string `json:"stderr,omitempty"`
	Error   string `json:"error,omitempty"`
}

func (c *agentConn) trackChatPending(id string) chan agentChatReply {
	ch := make(chan agentChatReply, 1)
	c.chatPendingMu.Lock()
	c.chatPending[id] = ch
	c.chatPendingMu.Unlock()
	return ch
}

func (c *agentConn) deliverChatReply(r agentChatReply) {
	c.chatPendingMu.Lock()
	ch, ok := c.chatPending[r.ID]
	if ok {
		delete(c.chatPending, r.ID)
	}
	c.chatPendingMu.Unlock()
	if ok {
		ch <- r
	}
}

// agentHub owns the connection registry and the dispatch entry point.
// All methods are safe for concurrent use.
type agentHub struct {
	mu    sync.Mutex
	byBot map[string]*agentConn // bot_user_id → conn
}

func newAgentHub() *agentHub {
	return &agentHub{byBot: map[string]*agentConn{}}
}

// register adds a new connection, kicking out any existing one on
// the same bot (last-write-wins). Returns the displaced conn (if
// any) so the caller can close its socket cleanly.
func (h *agentHub) register(c *agentConn) *agentConn {
	h.mu.Lock()
	defer h.mu.Unlock()
	prev := h.byBot[c.botUserID]
	h.byBot[c.botUserID] = c
	return prev
}

func (h *agentHub) unregister(c *agentConn) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if cur, ok := h.byBot[c.botUserID]; ok && cur == c {
		delete(h.byBot, c.botUserID)
	}
}

func (h *agentHub) lookup(botUserID string) *agentConn {
	h.mu.Lock()
	defer h.mu.Unlock()
	return h.byBot[botUserID]
}

// dispatchToolCall sends a tool_call to the agent attached to this
// bot and waits up to agentToolCallTimeout for the result.
// Caller-supplied id should be unique per call (we generate via
// generateResourceID at the call site).
func (h *agentHub) dispatchToolCall(botUserID, callID, tool string, args map[string]any) (*agentToolResult, error) {
	conn := h.lookup(botUserID)
	if conn == nil {
		return nil, errAgentNotAttached
	}
	payload, err := json.Marshal(agentToolCall{
		Kind: "tool_call",
		ID:   callID,
		Tool: tool,
		Args: args,
	})
	if err != nil {
		return nil, err
	}
	resultCh := conn.trackPending(callID)
	select {
	case conn.send <- payload:
	case <-conn.close:
		return nil, errAgentDisconnected
	case <-time.After(5 * time.Second):
		return nil, errAgentSendTimeout
	}
	select {
	case r := <-resultCh:
		return &r, nil
	case <-conn.close:
		return nil, errAgentDisconnected
	case <-time.After(agentToolCallTimeout):
		conn.pendingMu.Lock()
		delete(conn.pending, callID)
		conn.pendingMu.Unlock()
		return nil, errAgentTimeout
	}
}

// dispatchChatMessage sends a chat_message envelope to the agent
// (kimi-cli passthrough mode) and waits for the chat_reply. Long
// timeout — kimi can take a few minutes on big tasks.
func (h *agentHub) dispatchChatMessage(botUserID string, threadID int64, content string) (*agentChatReply, error) {
	conn := h.lookup(botUserID)
	if conn == nil {
		return nil, errAgentNotAttached
	}
	if !conn.hasCapability("kimi") {
		return nil, errAgentNoKimiCapability
	}
	id := generateResourceID()
	payload, err := json.Marshal(agentChatMessage{
		Kind:     "chat_message",
		ID:       id,
		ThreadID: threadID,
		Content:  content,
	})
	if err != nil {
		return nil, err
	}
	resultCh := conn.trackChatPending(id)
	select {
	case conn.send <- payload:
	case <-conn.close:
		return nil, errAgentDisconnected
	case <-time.After(5 * time.Second):
		return nil, errAgentSendTimeout
	}
	select {
	case r := <-resultCh:
		return &r, nil
	case <-conn.close:
		return nil, errAgentDisconnected
	case <-time.After(agentChatTimeout):
		conn.chatPendingMu.Lock()
		delete(conn.chatPending, id)
		conn.chatPendingMu.Unlock()
		return nil, errAgentTimeout
	}
}

// agentChatTimeout caps how long the platform waits for a
// chat_reply. Must comfortably exceed polar-agent's own kimi
// timeout (30min default, configurable via POLAR_KIMI_TIMEOUT) so
// the polar-agent's own timeout-with-partial-content path always
// runs first — otherwise the platform abandons the request and
// any reply that does eventually arrive is dropped.
const agentChatTimeout = 2 * time.Hour

var (
	errAgentNotAttached       = errors.New("agent not attached to this bot")
	errAgentDisconnected      = errors.New("agent disconnected before result arrived")
	errAgentSendTimeout       = errors.New("agent send buffer full")
	errAgentTimeout           = errors.New("agent did not return tool_result in time")
	errAgentNoKimiCapability  = errors.New("agent does not have kimi capability")
)
